// This is conceptual pseudocode showing what each stage produces.
// Real implementations (Babel, V8) use similar but more complex structures.

// ── Stage 1: Source text ────────────────────────────────────────
const source = 'let x = 42 + y;';

// ── Stage 2: Token stream (what a lexer produces) ───────────────
const tokens = [
  { type: 'keyword',    value: 'let' },
  { type: 'identifier', value: 'x' },
  { type: 'operator',   value: '=' },
  { type: 'number',     value: 42 },
  { type: 'operator',   value: '+' },
  { type: 'identifier', value: 'y' },
  { type: 'punctuation',value: ';' },
];

// ── Stage 3: AST node (simplified ESTree-style) ─────────────────
const ast = {
  type: 'VariableDeclaration',
  kind: 'let',
  declarations: [{
    type: 'VariableDeclarator',
    id:   { type: 'Identifier', name: 'x' },
    init: {
      type:     'BinaryExpression',
      operator: '+',
      left:     { type: 'Literal',    value: 42 },
      right:    { type: 'Identifier', name: 'y' },
    },
  }],
};

// ── Stage 4: Bytecode (conceptual; not real V8 bytecode) ─────────
// Real V8 Ignition bytecode is a binary format, but conceptually:
// LdaSmi [42]          -- Load small integer 42 into accumulator
// Star r0              -- Store accumulator into register 0
// Ldar a0              -- Load argument 'y' into accumulator
// Add r0               -- accumulator = accumulator + r0  → x = 42 + y
// Star r1              -- Store result into register 1 (x)

// ── In Node.js, you can see real bytecode via: ─────────────────
// node --print-bytecode --print-bytecode-filter=myFunction script.js
console.log('Inspect tokens and AST at: astexplorer.net');

// ── Pattern 1: Monomorphic vs. Polymorphic property access ─────
// V8 optimizes property access on objects with the same 'shape'
// (same property names in the same insertion order).

function getX(obj) { return obj.x; }

// Monomorphic: all calls see the same hidden class → fast inline cache
const p1 = { x: 1, y: 2 };
const p2 = { x: 3, y: 4 };
getX(p1); getX(p2); // V8 specializes to one hidden class

// Polymorphic: different shapes degrade the inline cache
const p3 = { y: 5, x: 6 }; // different insertion order → different hidden class!
getX(p3); // now polymorphic — V8 must handle multiple shapes

// Fix: always construct objects in the same property order.

// ── Pattern 2: Type-stable arithmetic runs at integer speed ────
function sumArray(arr) {
  let total = 0;           // starts as Smi (small integer)
  for (let i = 0; i < arr.length; i++) {
    total += arr[i];       // stays integer → TurboFan uses native ADD
  }
  return total;
}

console.log(sumArray([1, 2, 3, 4, 5])); // 15
// TurboFan can optimize this to near-C speed.

// Now what if we sneak in a float?
function sumBad(arr) {
  let total = 0;
  for (let i = 0; i < arr.length; i++) {
    total += arr[i]; // if arr has 1.5, total becomes float → deopt risk
  }
  return total;
}
console.log(sumBad([1, 2, 1.5, 2])); // 6.5 — V8 re-specializes to float

// ── Pattern 3: `delete` can drop an object into slow "dictionary mode" ──
const config = { host: 'a', port: 80, debug: true };
delete config.debug;      // object switches to hash-table property storage
// node --allow-natives-syntax: %HasFastProperties(config) → false

const config2 = { host: 'a', port: 80, debug: true };
config2.debug = undefined; // keeps the hidden class (or build a new object without the key)

// ── Pattern 4: Hidden class stability ─────────────────────────
function Point(x, y) {
  this.x = x; // always assign in the same order in the constructor
  this.y = y; // do NOT add properties after construction if possible
}
const points = Array.from({ length: 1000 }, (_, i) => new Point(i, i * 2));
// All points share the same hidden class → V8 optimizes aggressively

// ── Stack: local variables live in call frames ─────────────────
function factorial(n) {
  // Each recursive call creates a new stack frame with its own 'n'
  if (n <= 1) return 1;
  return n * factorial(n - 1); // n stack frames for input n
}
console.log(factorial(10)); // 3628800
// factorial(100000) → RangeError: Maximum call stack size exceeded

// ── Tail-call optimization (TCO) avoids stack growth ───────────
function factTail(n, acc = 1) {
  if (n <= 1) return acc;
  return factTail(n - 1, n * acc); // tail call: no work after the call
}
// ES2015 specifies proper tail calls, but only Safari's JavaScriptCore
// implements them — V8 (Chrome, Node, Deno) and SpiderMonkey (Firefox) do not,
// so factTail(100000) still overflows the stack in Node.
// Use iteration for deep recursion:
function factIterative(n) {
  let result = 1;
  for (let i = 2; i <= n; i++) result *= i;
  return result; // O(1) stack, O(n) time
}
console.log(factIterative(20)); // 2432902008176640000

// ── Heap: objects persist beyond the creating function ─────────
function makeCounter() {
  let count = 0;              // captured by a closure → stored in a heap Context
  return () => ++count;       // returned function closes over 'count'
}
const counter = makeCounter(); // makeCounter's stack frame is gone...
console.log(counter()); // 1   // ...but 'count' survives on the heap
console.log(counter()); // 2

// ── GC pressure: avoid short-lived allocations in hot loops ────
// Bad: creates a new array on the heap in every iteration
function sumBad(n) {
  let total = 0;
  for (let i = 0; i < n; i++) {
    const arr = [i, i * 2]; // heap allocation per iteration
    total += arr[0] + arr[1];
  }
  return total;
}
// Good: no allocation in the loop
function sumGood(n) {
  let total = 0;
  for (let i = 0; i < n; i++) {
    total += i + i * 2;      // pure arithmetic, no allocation
  }
  return total;
}
console.log(sumGood(1000000)); // fast, GC-pressure-free
